import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/UserPages.css";
import API_BASE_URL from "../config";

const SubscriptionCheckout = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { planName } = location.state || {};

  const [shippingInfo, setShippingInfo] = useState({
    fullName: "",
    address: "",
    city: "",
    state: "",
    zip: "",
    country: "USA",
  });

  const userId = sessionStorage.getItem("userId");

  const handleChange = (e) => {
    setShippingInfo({ ...shippingInfo, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!planName) {
      alert("Missing plan information. Please select a subscription plan first.");
      return navigate("/business-plans");
    }

    try {
      const estimatedDelivery = new Date();
      estimatedDelivery.setDate(estimatedDelivery.getDate() + Math.floor(Math.random() * 5) + 3);

      await fetch(`${API_BASE_URL}/api/subscriptions`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId,
          planName,
          shippingInfo,
          estimatedDelivery,
        }),
      });

      navigate("/subscription-confirmed");
    } catch (err) {
      console.error("Error subscribing:", err);
      alert("Failed to complete subscription.");
    }
  };

  return (
    <div>
      <Navbar />
      <div className="page-wrapper">
        <h2 className="page-title">🏋️ Subscription Checkout</h2>
        <p className="page-subtitle">Complete your shipping information to confirm your plan!</p>

        <form onSubmit={handleSubmit} className="checkout-form">
          <input 
            type="text" 
            name="fullName" 
            placeholder="Full Name" 
            value={shippingInfo.fullName}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="address" 
            placeholder="Address" 
            value={shippingInfo.address}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="city" 
            placeholder="City" 
            value={shippingInfo.city}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="state" 
            placeholder="State" 
            value={shippingInfo.state}
            onChange={handleChange}
            required
          />
          <input 
            type="text" 
            name="zip" 
            placeholder="ZIP Code" 
            value={shippingInfo.zip}
            onChange={handleChange}
            required
          />
          <button type="submit" className="subscribe-btn">
            Confirm Subscription
          </button>
        </form>
      </div>
      <Footer />
    </div>
  );
};

export default SubscriptionCheckout;
